def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each 4-marker emits a diagonal downward V, stopping at the row of 2s.
    barrier = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), h)
    for r in range(barrier):
        for c in range(w):
            if grid[r][c] == 4:
                for dr, dc in ((1, -1), (1, 1)):
                    rr, cc = r + 1, c + dc
                    while rr < barrier and 0 <= cc < w:
                        out[rr][cc] = 4
                        rr += 1
                        cc += dc
    return out
